CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) AND (_role <> 'admin' OR (auth.uid() = _user_id AND (coalesce(auth.jwt()->>'aal', '') = 'aal2' OR NOT EXISTS (SELECT 1 FROM auth.mfa_factors WHERE user_id = _user_id AND status = 'verified')))) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO anon, authenticated, service_role;
CREATE OR REPLACE FUNCTION public.guard_contact_message() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF length(trim(NEW.name)) NOT BETWEEN 1 AND 100 OR NEW.email !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' OR length(NEW.email) > 255 OR length(NEW.message) NOT BETWEEN 10 AND 5000 OR length(NEW.subject) > 200 THEN RAISE EXCEPTION 'Invalid message'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(lower(NEW.email), 0)); IF (SELECT count(*) FROM public.contact_messages WHERE lower(email) = lower(NEW.email) AND created_at > now() - interval '1 hour') >= 3 THEN RAISE EXCEPTION 'Please wait before sending another message'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.guard_contact_message() FROM PUBLIC;
CREATE TRIGGER protect_contact_messages BEFORE INSERT ON public.contact_messages FOR EACH ROW EXECUTE FUNCTION public.guard_contact_message();